/// @dev Copy of gold setUp; does not call parent setUp that wires Crane 18-dec dai/usdc as the SE book.
///      pairToken / rateAsset are MintableERC20Decimals. vaultShare / detfToken / claim / Bond NFT stay 18.
///      Crane usdc 18 is not 6-dec coverage. After Aerodrome address sort, roles stay pairToken vs rateAsset.
abstract contract TestBase_SingleStandardExchangeDETF_Decimals is TestBase_BalancerV3StandardExchangeRouter {
    using DetfFacetFactoryService for ICreate3FactoryProxy;
    using DetfPkgFactoryService for ICreate3FactoryProxy;
