    /// @dev Low-decimal LP books need larger funded payments so ordinary
    /// lifecycle tests exercise whole native DETF units rather than rounding to zero.
    function _fundedFixtureScale() internal pure returns (uint256) {
        return uint256(_pairDecimals()) + uint256(_rateDecimals()) < 18 ? 1_000_000 : 1;
    }

    /// @dev Fund `to` with production SE vault shares via deposit path.
    ///      Scale both seed and later payments identically, then convert each token to native units.
