    function _shiftUnderlyingPrice(bool buyUsdc_, uint256 amountIn_) internal {
        address trader_ = bob;
        address tokenIn_ = buyUsdc_ ? address(rateAsset) : address(pairToken);
        address tokenOut_ = buyUsdc_ ? address(pairToken) : address(rateAsset);
