        ISingleStandardExchangeDETFBonding(instance_).sellPositionToDetfNft(firstId_, 0, bonder_);

        userBondId_ = _bootstrapDetf(instance_, bonder_, 200e18);
        assertGt(
            _bondNftVault(instance_).effectiveSharesOf(userBondId_),
