        ISignatureTransfer.PermitTransferFrom memory permit_ = ISignatureTransfer.PermitTransferFrom({
            permitted: ISignatureTransfer.TokenPermissions({token: address(seShare0), amount: amt_}),
            nonce: 0,
            deadline: deadline_
        });
        bytes memory sig_ = _signPermit2(donorPk, address(seShare0), amt_, address(nft_), 0, deadline_);
        uint256 lpBeforeDonation_ = nft_.lpToken().balanceOf(address(nft_));
        vm.startPrank(donor);
