        bytes4[] memory funcs_ = multiVaultWeightedDetfExchangeInFacet.facetFuncs();
        address expectedFacet_ = address(multiVaultWeightedDetfExchangeInFacet);

        for (uint256 i; i < funcs_.length; ++i) {
