        amountsIn_[idx_] = shares_;
        vm.startPrank(joiner_);
        seShare0.transfer(address(bal_), shares_);
        bptOut_ = IBalancerV3StandardExchangeRouterProxy(address(seRouter)).prepayAddLiquidityUnbalanced(
