/// @notice Wave 1A P0/P1 adversarial coverage for SingleStandardExchangeDETF.
/// @dev Funded bond claims and staking redemption use the deployed child contracts.
contract Adversarial_SingleSE_P0_Test is TestBase_SingleStandardExchangeDETF_Adversarial, FundedBondLifecycleAssertions {
    // --- E5 / H3 / Guards ---

    function test_E5_zeroAmount_reverts() public {
        address instance_ = _openLiveOpenThreshold();
        vm.prank(attacker);
        vm.expectRevert(SingleStandardExchangeDETFRepo.ZeroAmount.selector);
        IStandardExchangeIn(instance_).exchangeIn(
            seShare, 0, IERC20(instance_), 0, attacker, false, block.timestamp + 1 hours
        );
    }

    function test_E5_expiredDeadline_reverts() public {
        address instance_ = _openLiveOpenThreshold();
        uint256 shares_ = _fundSeShares(attacker, 50e18);
        vm.startPrank(attacker);
        seShare.approve(instance_, shares_);
        vm.expectRevert(
            abi.encodeWithSelector(SingleStandardExchangeDETFRepo.DeadlineExpired.selector, block.timestamp - 1)
        );
        IStandardExchangeIn(instance_).exchangeIn(
            seShare, shares_, IERC20(instance_), 0, attacker, false, block.timestamp - 1
        );
        vm.stopPrank();
        assertEq(seShare.balanceOf(instance_), 0, "H3 residual shares");
    }

    function test_H3_minOutTooHigh_leavesNoInventory() public {
        address instance_ = _openLiveOpenThreshold();
        uint256 shares_ = _fundSeShares(attacker, 30e18);
        uint256 preview_ =
            IStandardExchangeIn(instance_).previewExchangeIn(seShare, shares_, IERC20(instance_));
        vm.startPrank(attacker);
        seShare.approve(instance_, shares_);
        vm.expectRevert();
        IStandardExchangeIn(instance_).exchangeIn(
            seShare, shares_, IERC20(instance_), preview_ + 1e18, attacker, false, block.timestamp + 1 hours
        );
        vm.stopPrank();
        _assertNoFreeInventory(instance_);
        assertEq(seShare.balanceOf(attacker), shares_, "shares refunded");
    }

    function test_preLive_mint_reverts() public {
        address instance_ = _deployOpenThresholdDetf("Adv Inert", "advI");
        uint256 shares_ = _fundSeShares(attacker, 50e18);
        vm.startPrank(attacker);
        seShare.approve(instance_, shares_);
        vm.expectRevert();
        IStandardExchangeIn(instance_).exchangeIn(
            seShare, shares_, IERC20(instance_), 0, attacker, false, block.timestamp + 1 hours
        );
        vm.stopPrank();
        assertEq(seShare.balanceOf(instance_), 0, "H3 residual");
    }

    // --- A donation ---

    function test_A1_donateVaultShares_cannotMintFreeDetf() public {
        address instance_ = _openLiveOpenThreshold();
        uint256 donated_ = _fundSeShares(attacker, 100e18);
        uint256 attBefore_ = IERC20(instance_).balanceOf(attacker);
        vm.prank(attacker);
        seShare.transfer(instance_, donated_);
        assertEq(seShare.balanceOf(instance_), donated_, "shares idle");
        assertEq(IERC20(instance_).balanceOf(attacker), attBefore_, "A1: no free DETF");

        uint256 victimIn_ = _fundSeShares(victim, 20e18);
        uint256 preview_ =
            IStandardExchangeIn(instance_).previewExchangeIn(seShare, victimIn_, IERC20(instance_));
        vm.startPrank(victim);
        seShare.approve(instance_, victimIn_);
        uint256 out_ = IStandardExchangeIn(instance_).exchangeIn(
            seShare, victimIn_, IERC20(instance_), 0, victim, false, block.timestamp + 1 hours
        );
        vm.stopPrank();
        assertEq(out_, preview_, "victim mint not inflated by idle donation");
    }

    function test_A2_donateDetfToDiamond_noTheft() public {
        address instance_ = _openLiveOpenThreshold();
        uint256 minted_ = _mintSeSharesToDetf(instance_, attacker, 40e18);
        uint256 donateAmt_ = minted_ / 2;
        if (donateAmt_ == 0) donateAmt_ = minted_;
        uint256 victimBefore_ = IERC20(instance_).balanceOf(victim);
        vm.prank(attacker);
        IERC20(instance_).transfer(instance_, donateAmt_);
        assertEq(IERC20(instance_).balanceOf(victim), victimBefore_, "victim unchanged");
        assertEq(IERC20(instance_).balanceOf(instance_), donateAmt_, "free detf on diamond");
    }

    function test_A3_cannotDrainBptWithoutBondAuthority() public {
        address instance_ = _openLiveOpenThreshold();
        IDetfBondNFT nft_ = IDetfBondNFT(ISingleStandardExchangeDETFInfo(instance_).bondNftVault());
        IERC20 lp_ = nft_.lpToken();
        uint256 held_ = lp_.balanceOf(address(nft_));
        assertGt(held_, 0, "protocol holds funded reserve LP");
        vm.prank(attacker);
        vm.expectRevert(abi.encodeWithSignature("NotAuthorized(address)", attacker));
        nft_.transferHeldToken(lp_, attacker, held_);
        assertEq(lp_.balanceOf(address(nft_)), held_, "reserve LP intact");
        assertEq(lp_.balanceOf(attacker), 0, "no LP extracted");
    }

    // --- D bond authority ---

    function test_D2_claimBond_nonOwner_reverts() public {
        address instance_ = _deployOpenThresholdDetf("Adv Claim Authority", "advCA");
        uint256 id_ = _bootstrapDetf(instance_, alice, 1_500e18);
        IDetfBondNFT nft_ = IDetfBondNFT(ISingleStandardExchangeDETFInfo(instance_).bondNftVault());
        vm.prank(attacker);
        vm.expectRevert(abi.encodeWithSignature("NotAuthorized(address)", attacker));
        nft_.claimBond(id_, attacker);
        assertEq(nft_.ownerOf(id_), alice, "owner unchanged");
        assertEq(nft_.positionOf(id_).claimedPrincipal, 0, "principal untouched");
    }

    function test_D3_fullBondClaim_retiresPosition() public {
        address instance_ = _deployOpenThresholdDetf("Adv Double Claim", "advDC");
        uint256 id_ = _bootstrapDetf(instance_, alice, 1_500e18);
        _assertBondMaturePreviewEqualsPayment(instance_, id_, alice);
        IDetfBondNFT nft_ = IDetfBondNFT(ISingleStandardExchangeDETFInfo(instance_).bondNftVault());
        uint256 held_ = _fundedBondStaking(instance_).balanceOf(alice);
        vm.prank(alice);
        vm.expectRevert(abi.encodeWithSignature("ERC721NonexistentToken(uint256)", id_));
        nft_.claimBond(id_, alice);
        assertEq(_fundedBondStaking(instance_).balanceOf(alice), held_, "no second payout");
    }

    function test_D5_lockClamp_minRevert_maxOk() public {
        address instance_ = _openLiveOpenThreshold();
        uint256 shares_ = _fundSeShares(attacker, 80e18);
        vm.startPrank(attacker);
        seShare.approve(instance_, shares_);
        vm.expectRevert();
        ISingleStandardExchangeDETFBonding(instance_).bond(
            seShare, shares_, 1 days, attacker, false, block.timestamp + 1 hours
        );
        (uint256 tid_,) = ISingleStandardExchangeDETFBonding(instance_).bond(
            seShare, shares_, DEFAULT_MAX_LOCK + 365 days, attacker, false, block.timestamp + 1 hours
        );
        vm.stopPrank();
        assertTrue(tid_ > 0, "clamped max lock");
    }

    function test_D6_cannotUnstakeMoreThanFundedBalance() public {
        address instance_ = _deployOpenThresholdDetf("Adv Funded D6", "advD6");
        uint256 id_ = _bootstrapDetf(instance_, alice, 2_500e18);
        _assertBondMaturePreviewEqualsPayment(instance_, id_, alice);
        uint256 held_ = _fundedBondStaking(instance_).balanceOf(alice);
        _assertFundedUnstakeRejected(instance_, alice, held_ + 1, IERC20(instance_), 0);
        _assertFundedUnstake(instance_, alice, held_ / 5);
        _assertFundedUnstakeRejected(instance_, alice, held_, IERC20(instance_), 0);
    }

    function test_H2_unstake_minOutTooHigh_balanceUnchanged() public {
        address instance_ = _deployOpenThresholdDetf("Adv Funded H2", "advH2");
        uint256 id_ = _bootstrapDetf(instance_, alice, 2_000e18);
        _assertBondMaturePreviewEqualsPayment(instance_, id_, alice);
        uint256 amount_ = _fundedBondStaking(instance_).balanceOf(alice) / 5;
        _assertFundedUnstakeRejected(instance_, alice, amount_, IERC20(instance_), amount_ + 1);
        _assertFundedUnstake(instance_, alice, amount_);
    }

    // --- F access ---

    function test_F2_bondNftVault_createFundedPosition_onlyDetf() public {
        address instance_ = _openLiveOpenThreshold();
        IDetfBondNFT nft_ = IDetfBondNFT(ISingleStandardExchangeDETFInfo(instance_).bondNftVault());
        vm.prank(attacker);
        vm.expectRevert(abi.encodeWithSignature("NotAuthorized(address)", attacker));
        nft_.createFundedPosition(1e9, DEFAULT_MIN_LOCK, attacker);
    }

    function test_F1_diamondCut_notCallableByAttacker() public {
        address instance_ = _openLiveOpenThreshold();
        (bool cutOk,) = instance_.call(
            abi.encodeWithSignature(
                "diamondCut((address,uint8,bytes4[])[],address,bytes)", new bytes(0), address(0), ""
            )
        );
        assertFalse(cutOk, "diamondCut blocked");
    }

    function test_F4_noSetWeights() public {
        address instance_ = _openLiveOpenThreshold();
        (bool ok,) = instance_.call(abi.encodeWithSignature("setWeights(uint256,uint256)", 1, 1));
        assertFalse(ok, "no setWeights");
    }

    // --- C reentrancy ---

    function test_C1_reenterBond_duringFirstBond_hitsIsLocked() public {
        address instance_ = _deployHostileShareDetf(1, type(uint256).max);
        bytes memory reentry = abi.encodeCall(
            DetfReentryTarget.reenterBondGeneric,
            (instance_, IERC20(address(hostileShare)), uint256(1e18), DEFAULT_MIN_LOCK, attacker)
        );
        hostileShare.arm(address(reentryTarget), reentry);

        vm.startPrank(alice);
        hostileShare.approve(instance_, 5_000e18);
        (uint256 tid_,) = ISingleStandardExchangeDETFBonding(instance_).bond(
            IERC20(address(hostileShare)),
            5_000e18,
            DEFAULT_MIN_LOCK,
            alice,
            false,
            block.timestamp + 1 hours
        );
        vm.stopPrank();

        assertTrue(tid_ > 0, "outer bond ok");
        assertEq(hostileShare.reentryAttempts(), 1, "C1 reentry attempted");
        assertFalse(hostileShare.nestedCallSucceeded(), "nested blocked");
        assertEq(hostileShare.nestedErrorSelector(), IReentrancyLock.IsLocked.selector, "C1 IsLocked");
        hostileShare.disarm();
    }

    function test_C3_mintReenterBond_hitsIsLocked() public {
        address instance_ = _deployHostileShareDetf(1, type(uint256).max);
        _bootstrapHostile(instance_, alice, 5_000e18);

        bytes memory reentry = abi.encodeCall(
            DetfReentryTarget.reenterBondGeneric,
            (instance_, IERC20(address(hostileShare)), uint256(1e18), DEFAULT_MIN_LOCK, attacker)
        );
        hostileShare.arm(address(reentryTarget), reentry);

        uint256 amountIn_ = 50e18;
        vm.startPrank(attacker);
        hostileShare.approve(instance_, amountIn_);
        IStandardExchangeIn(instance_).exchangeIn(
            IERC20(address(hostileShare)),
            amountIn_,
            IERC20(instance_),
            0,
            attacker,
            false,
            block.timestamp + 1 hours
        );
        vm.stopPrank();

        assertEq(hostileShare.reentryAttempts(), 1, "C3 reentry");
        assertFalse(hostileShare.nestedCallSucceeded(), "nested blocked");
        assertEq(hostileShare.nestedErrorSelector(), IReentrancyLock.IsLocked.selector, "C3 IsLocked");
        hostileShare.disarm();
    }

    function test_C2_reenterExchangeIn_duringMint_hitsIsLocked() public {
        address instance_ = _deployHostileShareDetf(1, type(uint256).max);
        _bootstrapHostile(instance_, alice, 5_000e18);

        bytes memory reentry = abi.encodeCall(
            DetfReentryTarget.reenterExchangeIn,
            (instance_, IERC20(address(hostileShare)), uint256(1e18), IERC20(instance_), attacker)
        );
        hostileShare.arm(address(reentryTarget), reentry);

        vm.startPrank(attacker);
        hostileShare.approve(instance_, 50e18);
        IStandardExchangeIn(instance_).exchangeIn(
            IERC20(address(hostileShare)),
            50e18,
            IERC20(instance_),
            0,
            attacker,
            false,
            block.timestamp + 1 hours
        );
        vm.stopPrank();

        assertEq(hostileShare.reentryAttempts(), 1, "C2 reentry");
        assertFalse(hostileShare.nestedCallSucceeded(), "nested blocked");
        assertEq(hostileShare.nestedErrorSelector(), IReentrancyLock.IsLocked.selector, "C2 IsLocked");
        hostileShare.disarm();
    }

    // --- E economic / B thresholds ---

    function test_E1_mintThenPartialBurn_conservation() public {
        address instance_ = _openLiveOpenThreshold();
        uint256 sharesIn_ = _fundSeShares(attacker, 40e18);
        vm.startPrank(attacker);
        seShare.approve(instance_, sharesIn_);
        uint256 detfOut_ = IStandardExchangeIn(instance_).exchangeIn(
            seShare, sharesIn_, IERC20(instance_), 0, attacker, false, block.timestamp + 1 hours
        );
        vm.stopPrank();
        assertTrue(detfOut_ > 0, "minted");

        uint256 burnAmt_ = detfOut_ / 2;
        if (burnAmt_ == 0) burnAmt_ = detfOut_;
        vm.startPrank(attacker);
        IERC20(instance_).approve(instance_, burnAmt_);
        uint256 sharesBack_ = IStandardExchangeIn(instance_).exchangeIn(
            IERC20(instance_), burnAmt_, seShare, 0, attacker, false, block.timestamp + 1 hours
        );
        vm.stopPrank();
        assertGt(sharesBack_, 0, "partial redemption executes");
        assertLe(sharesBack_, sharesIn_, "E1: partial out <= in");
        _assertNoFreeInventory(instance_);
    }

    function test_E4_holderBalance_notDilutedByOthersMint() public {
        address instance_ = _openLiveOpenThreshold();
        uint256 holderOut_ = _mintSeSharesToDetf(instance_, victim, 30e18);
        uint256 victimBal_ = IERC20(instance_).balanceOf(victim);
        assertTrue(holderOut_ > 0 && victimBal_ > 0, "victim holds");
        _mintSeSharesToDetf(instance_, attacker, 20e18);
        assertEq(IERC20(instance_).balanceOf(victim), victimBal_, "E4: victim DETF unchanged");
    }

    function test_B3_thresholdGates_coupleToSynthetic() public {
        // Default-threshold instance from setUp detf
        _bootstrapViaFirstBond(alice, 2_000e18);
        uint256 synth_ = detfInfo.syntheticPrice();
        assertEq(detfInfo.isMintingAllowed(), synth_ > detfInfo.mintThreshold(), "B3 mint coupling");
        assertEq(detfInfo.isBurningAllowed(), synth_ < detfInfo.burnThreshold(), "B3 burn coupling");
    }

    function test_B1_openThresholds_mintBurn_boundsSafety() public {
        address instance_ = _openLiveOpenThreshold();
        uint256 victimOut_ = _mintSeSharesToDetf(instance_, victim, 30e18);
        uint256 victimBal_ = IERC20(instance_).balanceOf(victim);

        uint256 sharesIn_ = _fundSeShares(attacker, 50e18);
        vm.startPrank(attacker);
        seShare.approve(instance_, sharesIn_);
        uint256 detfOut_ = IStandardExchangeIn(instance_).exchangeIn(
            seShare, sharesIn_, IERC20(instance_), 0, attacker, false, block.timestamp + 1 hours
        );
        vm.stopPrank();

        assertGt(detfOut_, 0, "attacker funded DETF");
        {
            vm.startPrank(attacker);
            IERC20(instance_).approve(instance_, detfOut_);
            IStandardExchangeIn(instance_).exchangeIn(
                IERC20(instance_), detfOut_, seShare, 0, attacker, false, block.timestamp + 1 hours
            );
            vm.stopPrank();
        }

        assertEq(IERC20(instance_).balanceOf(victim), victimBal_, "B1: victim balance intact");
        assertTrue(victimOut_ > 0, "victim still has position basis");
        _assertNoFreeInventory(instance_);
    }
}

// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;

import {IDETFFundedRewards} from "contracts/interfaces/IStakedDETF.sol";
import {IDETFStandardizedYield, IDETFStakingPreview} from "contracts/interfaces/IDETFStandardizedYield.sol";

import {IERC20} from "@crane/contracts/interfaces/IERC20.sol";
import {IFacet} from "@crane/contracts/interfaces/IFacet.sol";
import {IDiamondLoupe} from "@crane/contracts/interfaces/IDiamondLoupe.sol";
import {IStandardExchangeIn} from "@crane/contracts/interfaces/IStandardExchangeIn.sol";
import {
    TestBase_SingleStandardExchangeDETF_Adversarial
} from "test/foundry/spec/vaults/detf/protocols/dexes/balancer/v3/standardExchange/single/adversarial/TestBase_SingleStandardExchangeDETF_Adversarial.sol";
import {ILegacySingleStandardExchangeDETFBonding as ISingleStandardExchangeDETFBonding} from "contracts/vaults/detf/protocols/dexes/balancer/v3/standardExchange/single/TestBase_SingleStandardExchangeDETF.sol";
import {ISingleStandardExchangeDETFBonding as ISingleStandardExchangeDETFBondingSelectorSource} from "contracts/vaults/detf/protocols/dexes/balancer/v3/standardExchange/single/SingleStandardExchangeDETFBondingTarget.sol";
import {ILegacySingleStandardExchangeDETFInfo as ISingleStandardExchangeDETFInfo} from "contracts/vaults/detf/protocols/dexes/balancer/v3/standardExchange/single/TestBase_SingleStandardExchangeDETF.sol";
import {ISingleStandardExchangeDETFInfo as ISingleStandardExchangeDETFInfoSelectorSource} from "contracts/vaults/detf/protocols/dexes/balancer/v3/standardExchange/single/SingleStandardExchangeDETFInfoTarget.sol";
import {
    SingleStandardExchangeDETFRepo
} from "contracts/vaults/detf/protocols/dexes/balancer/v3/standardExchange/single/SingleStandardExchangeDETFRepo.sol";

/// @notice Catalog J1–J3 surface suite for Balancer Single SE DETF (WP-J-DETF-SSE-001).
/// @dev J3 smokes **proxy** (registry-deployed diamond), never facet implementation address.
contract Adversarial_SingleSE_Surface_Test is TestBase_SingleStandardExchangeDETF_Adversarial {
    /// @dev Target-derived control set: money + info + bonding selectors (not incomplete Facet copy).
    function _controlSelectors() internal pure returns (bytes4[] memory sels_) {
        sels_ = new bytes4[](28);
        sels_[0] = IStandardExchangeIn.exchangeIn.selector;
        sels_[1] = IStandardExchangeIn.previewExchangeIn.selector;
        sels_[2] = ISingleStandardExchangeDETFBondingSelectorSource.bond.selector;
        sels_[3] = ISingleStandardExchangeDETFBondingSelectorSource.previewBond.selector;
        sels_[4] = ISingleStandardExchangeDETFBondingSelectorSource.acceptedBondTokens.selector;
        sels_[5] = ISingleStandardExchangeDETFBondingSelectorSource.joinDonatedCapital.selector;
        sels_[6] = ISingleStandardExchangeDETFBondingSelectorSource.notifyReserveDonated.selector;
        sels_[7] = ISingleStandardExchangeDETFBondingSelectorSource.donate.selector;
        sels_[8] = ISingleStandardExchangeDETFInfoSelectorSource.isReserveLive.selector;
        sels_[9] = ISingleStandardExchangeDETFInfoSelectorSource.standardExchangeVault.selector;
        sels_[10] = ISingleStandardExchangeDETFInfoSelectorSource.standardExchangeVaultShare.selector;
        sels_[11] = ISingleStandardExchangeDETFInfoSelectorSource.rateTarget.selector;
        sels_[12] = ISingleStandardExchangeDETFInfoSelectorSource.reservePool.selector;
        sels_[13] = ISingleStandardExchangeDETFInfoSelectorSource.syntheticPrice.selector;
        sels_[14] = ISingleStandardExchangeDETFInfoSelectorSource.mintThreshold.selector;
        sels_[15] = ISingleStandardExchangeDETFInfoSelectorSource.burnThreshold.selector;
        sels_[16] = ISingleStandardExchangeDETFInfoSelectorSource.isMintingAllowed.selector;
        sels_[17] = ISingleStandardExchangeDETFInfoSelectorSource.isBurningAllowed.selector;
        sels_[18] = ISingleStandardExchangeDETFInfoSelectorSource.bondNftVault.selector;
        sels_[19] = ISingleStandardExchangeDETFInfoSelectorSource.rebasingClaimToken.selector;
        sels_[20] = ISingleStandardExchangeDETFInfoSelectorSource.lastExpansionTimestamp.selector;
        sels_[21] = ISingleStandardExchangeDETFInfoSelectorSource.epochAnchor.selector;
        sels_[22] = ISingleStandardExchangeDETFInfoSelectorSource.expansionClosureRatePerSecond.selector;
        sels_[23] = ISingleStandardExchangeDETFInfoSelectorSource.pendingExpansionDetf.selector;
        sels_[24] = IDETFFundedRewards.synchronizeRewards.selector;
        sels_[25] = IDETFStandardizedYield.rawSY.selector;
        sels_[26] = IDETFStandardizedYield.stakingSY.selector;
        sels_[27] = IDETFStakingPreview.previewStakingGonsPerUnit.selector;
    }

    function _facetFuncsContains(bytes4[] memory funcs_, bytes4 sel_) internal pure returns (bool) {
        for (uint256 i; i < funcs_.length; ++i) {
            if (funcs_[i] == sel_) return true;
        }
        return false;
    }

    /// @notice J1: Target/product API selectors ⊆ Facet.facetFuncs().
    function test_J1_facetFuncs_coversTargetApi() public view {
        bytes4[] memory exchange_ = singleStandardExchangeDetfExchangeInFacet.facetFuncs();
        bytes4[] memory bonding_ = singleStandardExchangeDetfBondingFacet.facetFuncs();
        bytes4[] memory controls_ = _controlSelectors();
        for (uint256 i_; i_ < controls_.length; ++i_) {
            assertTrue(_facetFuncsContains(exchange_, controls_[i_]) || _facetFuncsContains(bonding_, controls_[i_]),
                "current product selector declared");
        }
        assertFalse(_facetFuncsContains(bonding_, ISingleStandardExchangeDETFBonding.sellPositionToDetfNft.selector));
        assertFalse(_facetFuncsContains(bonding_, ISingleStandardExchangeDETFInfo.thresholdMode.selector));
    }

    /// @notice J2: loupe facetAddress(sel) != 0 for all product controls on production proxy.
    function test_J2_proxyLoupe_allProductSelectors() public {
        address instance_ = _openLiveOpenThreshold();
        IDiamondLoupe loupe_ = IDiamondLoupe(instance_);
        bytes4[] memory controls_ = _controlSelectors();
        for (uint256 i; i < controls_.length; ++i) {
            address facetAddr_ = loupe_.facetAddress(controls_[i]);
            assertTrue(facetAddr_ != address(0), "J2 loupe zero facet");
            // Must not be the diamond itself or zero — and must not be a bare standalone new-facet.
            assertTrue(facetAddr_ != instance_, "J2 facet != proxy");
        }
    }

    /// @notice J3: smoke-call money + view selectors on **proxy** (not facet impl address).
    function test_J3_proxyCallable_smoke_eachSelector() public {
        address instance_ = _openLiveOpenThreshold();
        // Prove we are not calling facet impl: loupe maps exchangeIn to a non-zero facet.
        address exchangeFacet_ =
            IDiamondLoupe(instance_).facetAddress(IStandardExchangeIn.exchangeIn.selector);
        assertTrue(exchangeFacet_ != address(0) && exchangeFacet_ != instance_, "proxy cut");

        // --- Views on proxy ---
        assertTrue(ISingleStandardExchangeDETFInfo(instance_).isReserveLive());
        assertTrue(ISingleStandardExchangeDETFInfo(instance_).standardExchangeVault() != address(0));
        assertTrue(ISingleStandardExchangeDETFInfo(instance_).standardExchangeVaultShare() != address(0));
        assertTrue(ISingleStandardExchangeDETFInfo(instance_).reservePool() != address(0));
        assertTrue(ISingleStandardExchangeDETFInfo(instance_).bondNftVault() != address(0));
        ISingleStandardExchangeDETFInfo(instance_).rateTarget();
        ISingleStandardExchangeDETFInfo(instance_).syntheticPrice();
        ISingleStandardExchangeDETFInfo(instance_).mintThreshold();
        ISingleStandardExchangeDETFInfo(instance_).burnThreshold();
        ISingleStandardExchangeDETFInfo(instance_).isMintingAllowed();
        ISingleStandardExchangeDETFInfo(instance_).isBurningAllowed();
        ISingleStandardExchangeDETFInfo(instance_).lastExpansionTimestamp();
        ISingleStandardExchangeDETFInfo(instance_).expansionClosureRatePerSecond();

        // preview on proxy (no state)
        IStandardExchangeIn(instance_).previewExchangeIn(seShare, 1e18, IERC20(instance_));

        // Money path: ZeroAmount proves selector is live on proxy (exact product error).
        vm.prank(attacker);
        vm.expectRevert(SingleStandardExchangeDETFRepo.ZeroAmount.selector);
        IStandardExchangeIn(instance_).exchangeIn(
            seShare, 0, IERC20(instance_), 0, attacker, false, block.timestamp + 1 hours
        );

        vm.prank(attacker);
        vm.expectRevert(SingleStandardExchangeDETFRepo.ZeroAmount.selector);
        ISingleStandardExchangeDETFBonding(instance_).bond(
            seShare, 0, DEFAULT_MIN_LOCK, attacker, false, block.timestamp + 1 hours
        );

        ISingleStandardExchangeDETFInfoSelectorSource(instance_).rebasingClaimToken();
        ISingleStandardExchangeDETFBondingSelectorSource(instance_).acceptedBondTokens();
        IDETFFundedRewards(instance_).synchronizeRewards();
        assertTrue(IDETFStandardizedYield(instance_).rawSY() != address(0));
        assertTrue(IDETFStandardizedYield(instance_).stakingSY() != address(0));
        assertGt(IDETFStakingPreview(instance_).previewStakingGonsPerUnit(IERC20(instance_), 0), 0);

        // Explicit anti-theater: do not smoke-call facet implementation address as primary SUT.
        // (Calling impl without diamond context would mis-attribute storage; J3 is proxy-only.)
        assertTrue(exchangeFacet_ != instance_, "J3 primary target is proxy");
    }
}

