abstract contract Adversarial_SingleSE_A0Crops_Decimals is TestBase_SingleStandardExchangeDETF_Adversarial_Decimals, FundedBondLifecycleAssertions {
    function test_A0_preLive_donatedVaultShare_cannotBeFirstMinted() public {
